mapper.select:
SELECT a.*, b.product_name, b.product_code, c.owner_code, c.owner_name, d.location_code, d.location_type, d.location_category, e.zone_name, e.zone_type, f.warehouse_name FROM wms_inventory a, wms_products b, wms_cargo_owners c, wms_storage_locations d, wms_storage_zones e, wms_warehouses f WHERE a.product_id = b.id and b.owner_id = c.id and a.location_code = d.location_code and d.zone_id=e.id and f.id=e.warehouse_id
AND b.product_name LIKE concat('%',#{productName},'%')
AND b.product_code = #{productCode}
AND c.owner_code = #{ownerCode}
AND c.owner_name LIKE concat('%',#{ownerName},'%')
AND f.warehouse_name LIKE concat('%',#{warehouseName},'%')
AND f.warehouse_code = #{warehouseCode}
AND e.zone_type = #{zoneType}
AND d.location_code = #{locationCode}
